/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first and, under each one, every reply that descends from it — directly or
 * through other replies — in posting order. A deleted comment stays in place
 * as a placeholder with its text removed, so the replies under it stay put.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt), asc(comments.id))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const byId = new Map(decorated.map((comment) => [comment.id, comment]));
  const repliesByRoot = new Map<string, CommentWithAuthor[]>();
  const roots: CommentWithAuthor[] = [];

  for (const comment of decorated) {
    if (comment.parentId === null) {
      roots.push(comment);
      continue;
    }
    const root = rootIdOf(comment, byId);
    if (root === null) continue;
    const bucket = repliesByRoot.get(root) ?? [];
    bucket.push(comment);
    repliesByRoot.set(root, bucket);
  }

  return roots.map((comment) => ({
    comment: asPlaceholder(comment),
    replies: (repliesByRoot.get(comment.id) ?? []).map(asPlaceholder),
  }));
}

/** Walks parent links to the top-level comment. Cycles and dangling parents yield null. */
function rootIdOf(
  comment: CommentWithAuthor,
  byId: ReadonlyMap<string, CommentWithAuthor>,
): string | null {
  const seen = new Set<string>();
  let current: CommentWithAuthor | undefined = comment;
  while (current !== undefined && current.parentId !== null) {
    if (seen.has(current.id)) return null;
    seen.add(current.id);
    const parent = byId.get(current.parentId);
    if (parent === undefined) return null;
    current = parent;
  }
  return current === undefined ? null : current.id;
}

/** A deleted comment keeps its place but not its text. */
function asPlaceholder(comment: CommentWithAuthor): CommentWithAuthor {
  if (comment.archivedAt === null) return comment;
  return { ...comment, body: "" };
}

