function isPastEditWindow(comment: Comment): boolean {
  // Counted from the original posting. An edit must not open a new window.
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * Mentions are exactly the active members of this workspace whose handle
 * appears in the text (outside code). The author's own handle is ignored,
 * and ids supplied by the client are not trusted.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  authorId: UserId,
): Promise<readonly UserId[]> {
  const members = await memberRepo.listActiveMembers(orgId);
  return resolveMentions(body, members).filter((userId) => userId !== authorId);
}

