input.new_string:
subscribe("comment.created", async (payload) => {
  const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
  const comment = await commentRepo.findCommentById(
    payload.orgId,
    payload.commentId,
  );

  const watchers = new Set<UserId>();
  if (issue) {
    watchers.add(issue.authorId);
    if (issue.assigneeId) watchers.add(issue.assigneeId);
  }
  if (comment?.parentId) {
    const parent = await commentRepo.findCommentById(
      payload.orgId,
      comment.parentId,
    );
    if (parent) watchers.add(parent.authorId);
  }

  // A mention takes precedence: one alert per person per comment.
  const mentioned = new Set(payload.mentionedUserIds);
  const commentRecipients = [...watchers].filter((id) => !mentioned.has(id));

  await notify(payload.orgId, "comment_created", commentRecipients, {
    title: "New comment",
    body: `A comment was added to issue ${payload.issueId}`,
    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  });

  if (mentioned.size > 0) {
    await notify(payload.orgId, "comment_mention", [...mentioned], {
      title: "You were mentioned",
      body: `You were mentioned on issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });
  }
});

subscribe("comment.updated", async (payload) => {
  if (payload.newlyMentionedUserIds.length === 0) return;
  await notify(
    payload.orgId,
    "comment_mention",
    payload.newlyMentionedUserIds,
    {
      title: "You were mentioned",
      body: `You were mentioned on issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    },
  );
});

